INSERT INTO recipes (id, title, ingredients, steps, prep_time, cook_time, servings, tags, language) VALUES
  ('tablewise:diet:v1:paleo-thai-basil-chicken-lettuce-cups', 'Thai basil chicken lettuce cups', ARRAY['2 tbsp coconut oil', '500 g minced chicken', '3 cloves garlic, finely chopped', '1 red chilli, finely sliced', '3 tbsp coconut aminos', '1 lime, juiced', '20 g fresh Thai basil leaves', '2 little gem lettuces, leaves separated', '1 carrot, cut into matchsticks']::text[], ARRAY['Heat the coconut oil in a large frying pan over a high heat.', 'Add the minced chicken and fry for 6–8 minutes, breaking it up, until browned and cooked through to 74°C.', 'Stir in the garlic and chilli and cook for 1 minute until fragrant.', 'Add the coconut aminos and lime juice, bubble for 1 minute, then stir through the basil until it wilts.', 'Spoon the chicken into the lettuce leaves, top with the carrot and serve straight away.']::text[], 15, 10, '4', ARRAY['Dinner', 'Paleo', 'Thai', 'Chicken', 'Gluten-free', 'Dairy-free', 'ai-generated']::text[], 'en'),
  ('tablewise:diet:v1:paleo-korean-beef-cauliflower-bowl', 'Korean-style beef with garlic cauliflower', ARRAY['1 cauliflower, coarsely grated', '2 tbsp avocado oil', '400 g beef sirloin, thinly sliced', '2 cloves garlic, grated', '1 thumb fresh ginger, grated', '3 tbsp coconut aminos', '1 tsp toasted sesame oil', '4 spring onions, sliced', '1 tbsp sesame seeds']::text[], ARRAY['Heat 1 tbsp of the avocado oil in a large frying pan over a medium heat and cook the grated cauliflower for 5 minutes until just tender. Tip into bowls.', 'Wipe out the pan, add the remaining oil and turn the heat to high. Fry the beef in two batches for 2 minutes until browned, then return it all to the pan.', 'Add the garlic and ginger and fry for 30 seconds, then add the coconut aminos and sesame oil and toss to coat.', 'Spoon the beef over the cauliflower and scatter with the spring onions and sesame seeds.']::text[], 15, 15, '4', ARRAY['Dinner', 'Paleo', 'Korean', 'Beef', 'Gluten-free', 'Dairy-free', 'ai-generated']::text[], 'en'),
  ('tablewise:diet:v1:paleo-lemon-herb-chicken-sweet-potatoes', 'Lemon and herb chicken with sweet potatoes', ARRAY['8 bone-in chicken thighs', '600 g sweet potatoes, cut into chunks', '1 red onion, cut into wedges', '3 tbsp olive oil', '1 lemon, zested and juiced', '2 tsp dried thyme', '3 cloves garlic, crushed', '1 tsp sea salt', '0.5 tsp black pepper']::text[], ARRAY['Heat the oven to 200°C (fan 180°C).', 'Toss the sweet potatoes and onion with half the olive oil on a large baking tray.', 'Rub the chicken with the remaining oil, lemon zest, thyme, garlic, salt and pepper, and sit it on the vegetables skin side up.', 'Roast for 40 minutes until the skin is crisp and the thickest part reaches 74°C with clear juices.', 'Squeeze over the lemon juice and serve.']::text[], 15, 40, '4', ARRAY['Dinner', 'Paleo', 'British', 'Chicken', 'Gluten-free', 'Dairy-free', 'ai-generated']::text[], 'en'),
  ('tablewise:diet:v1:paleo-salmon-asparagus-traybake', 'Salmon and asparagus traybake', ARRAY['4 salmon fillets', '300 g asparagus, woody ends snapped off', '250 g cherry tomatoes', '2 tbsp olive oil', '1 lemon, sliced', '1 tsp sea salt', '0.5 tsp black pepper']::text[], ARRAY['Heat the oven to 200°C (fan 180°C).', 'Toss the asparagus and tomatoes with the olive oil, salt and pepper on a baking tray and roast for 8 minutes.', 'Add the salmon, top each fillet with lemon slices and roast for 10 minutes more until the fish is opaque and flakes easily.', 'Serve straight from the tray.']::text[], 10, 18, '4', ARRAY['Dinner', 'Paleo', 'Mediterranean', 'Fish', 'Gluten-free', 'Dairy-free', 'ai-generated']::text[], 'en'),
  ('tablewise:diet:v1:paleo-sweet-potato-spinach-hash', 'Sweet potato and spinach breakfast hash', ARRAY['2 tbsp avocado oil', '500 g sweet potatoes, diced small', '1 red pepper, diced', '1 onion, diced', '100 g baby spinach', '4 eggs', '0.5 tsp smoked paprika', '0.5 tsp sea salt']::text[], ARRAY['Heat the oil in a large frying pan over a medium heat and fry the sweet potatoes for 10 minutes, stirring often, until golden and almost tender.', 'Add the pepper, onion, paprika and salt and cook for 5 minutes more.', 'Stir in the spinach until it wilts, then make four hollows and crack an egg into each.', 'Cover the pan and cook for 4–5 minutes until the whites are set and the yolks are cooked to your liking.']::text[], 10, 20, '4', ARRAY['Breakfast', 'Paleo', 'American', 'Eggs', 'Gluten-free', 'Dairy-free', 'ai-generated']::text[], 'en'),
  ('tablewise:diet:v1:carnivore-pan-seared-ribeye', 'Pan-seared ribeye with butter', ARRAY['2 ribeye steaks', '1 tsp flaky salt', '40 g butter']::text[], ARRAY['Take the steaks out of the fridge 20 minutes before cooking and season both sides with the salt.', 'Heat a heavy frying pan over a high heat until very hot.', 'Sear the steaks for 3 minutes on each side, then add the butter and spoon it over them for 1 minute. They should reach at least 63°C.', 'Rest the steaks for 5 minutes before slicing and pour over the pan butter.']::text[], 5, 12, '4', ARRAY['Dinner', 'Carnivore', 'American', 'Beef', 'Gluten-free', 'ai-generated']::text[], 'en'),
  ('tablewise:diet:v1:carnivore-crispy-chicken-thighs', 'Crispy roast chicken thighs', ARRAY['8 bone-in chicken thighs, skin on', '1.5 tsp sea salt', '20 g beef dripping']::text[], ARRAY['Heat the oven to 220°C (fan 200°C).', 'Pat the chicken dry and rub with the salt.', 'Melt the dripping in a roasting tin in the oven for 3 minutes, add the chicken skin side down, then turn it skin side up.', 'Roast for 35–40 minutes until the skin is crisp and the thickest part reaches 74°C with clear juices.']::text[], 5, 40, '4', ARRAY['Dinner', 'Carnivore', 'British', 'Chicken', 'Gluten-free', 'Dairy-free', 'ai-generated']::text[], 'en'),
  ('tablewise:diet:v1:carnivore-smoked-salmon-scrambled-eggs', 'Scrambled eggs with smoked salmon', ARRAY['8 eggs', '30 g butter', '200 g smoked salmon', '0.5 tsp salt']::text[], ARRAY['Beat the eggs with the salt in a mixing bowl.', 'Melt the butter in a saucepan over a low heat.', 'Add the eggs and stir slowly for 3–4 minutes until softly set and cooked through.', 'Spoon onto plates and drape the smoked salmon alongside.']::text[], 5, 5, '4', ARRAY['Breakfast', 'Carnivore', 'British', 'Fish', 'Gluten-free', 'ai-generated']::text[], 'en'),
  ('tablewise:diet:v1:carnivore-beef-patties', 'Beef patties with cheddar', ARRAY['600 g beef mince', '1 tsp salt', '4 slices cheddar cheese', '1 tbsp beef dripping']::text[], ARRAY['Mix the mince with the salt in a mixing bowl and shape into four patties about 2 cm thick.', 'Heat the dripping in a large frying pan over a medium-high heat.', 'Fry the patties for 4–5 minutes on each side until no pink remains and they reach 71°C.', 'Lay a cheddar slice on each for the last minute, cover the pan so it melts, and serve.']::text[], 10, 10, '4', ARRAY['Dinner', 'Carnivore', 'American', 'Beef', 'Gluten-free', 'ai-generated']::text[], 'en'),
  ('tablewise:diet:v1:carnivore-lamb-chops', 'Grilled lamb chops', ARRAY['8 lamb chops', '1 tsp sea salt', '20 g butter, melted']::text[], ARRAY['Heat the grill to high.', 'Brush the chops with the melted butter and season with the salt.', 'Grill on a rack in the oven for 4–5 minutes on each side until they reach at least 63°C, then rest for 3 minutes before serving.']::text[], 5, 10, '4', ARRAY['Dinner', 'Carnivore', 'French', 'Lamb', 'Gluten-free', 'ai-generated']::text[], 'en')
